import{_ as e,o as a,c as r,a3 as o}from"./chunks/framework.BlfGB29P.js";const b=JSON.parse('{"title":"AST 与代码工具全景","description":"","frontmatter":{"title":"AST 与代码工具全景","outline":[2,3]},"headers":[],"relativePath":"frontend/topics/ast-tooling/index.md","filePath":"frontend/topics/ast-tooling/index.md","lastUpdated":1785589115000}'),n={name:"frontend/topics/ast-tooling/index.md"};function s(i,t,d,l,c,p){return a(),r("div",null,[...t[0]||(t[0]=[o(`<h1 id="ast-与代码工具全景" tabindex="-1">AST 与代码工具全景 <a class="header-anchor" href="#ast-与代码工具全景" aria-label="Permalink to &quot;AST 与代码工具全景&quot;">​</a></h1><blockquote><p>作者：codex-gpt-sol-5.6</p></blockquote><p>代码格式化、Lint、编译转换、依赖分析和批量迁移都需要回答同一个问题：怎样在不误解源代码的前提下读取、判断并修改它。字符串替换只看字符，AST（Abstract Syntax Tree，抽象语法树）则把代码表示为具有类型和父子关系的节点，使工具能够区分“变量名”“字符串内容”和“对象属性”等不同语法角色。</p><p>本组文章建立一条完整链路：从字符经过 Parser 变成 AST，再完成遍历、作用域与类型分析，随后执行变换、打印并生成 Source Map，最后把这些能力封装成 Babel/SWC 插件、ESLint 规则和 Codemod。它不展开编译器后端、机器码生成和语言虚拟机实现。</p><h2 id="_1-代码工具流水线" tabindex="-1">1. 代码工具流水线 <a class="header-anchor" href="#_1-代码工具流水线" aria-label="Permalink to &quot;1. 代码工具流水线&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>源代码</span></span>
<span class="line"><span>  -&gt; 词法分析：字符组成 Token</span></span>
<span class="line"><span>  -&gt; 语法分析：Token 按文法组成 CST / AST</span></span>
<span class="line"><span>  -&gt; 语义分析：建立作用域、绑定、引用和类型</span></span>
<span class="line"><span>  -&gt; 变换：匹配节点并生成新节点</span></span>
<span class="line"><span>  -&gt; 代码生成：恢复括号、空白、注释和 Source Map</span></span>
<span class="line"><span>  -&gt; 工具集成：插件、Lint 规则、Codemod、构建流程</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p>并非每个工具都会走完全部阶段。ESLint 通常只分析并报告，格式化器主要重新打印，Codemod 会修改源码，而 TypeScript 类型工具必须建立 <code>Program</code> 和 <code>TypeChecker</code> 才能获得跨文件语义。</p><h2 id="_2-核心对象与职责" tabindex="-1">2. 核心对象与职责 <a class="header-anchor" href="#_2-核心对象与职责" aria-label="Permalink to &quot;2. 核心对象与职责&quot;">​</a></h2><table tabindex="0"><thead><tr><th>对象</th><th>负责什么</th><th>不负责什么</th></tr></thead><tbody><tr><td>Token</td><td>记录关键字、标识符、字面量和标点及其位置</td><td>不表达完整嵌套关系</td></tr><tr><td>CST</td><td>尽量保留产生式、括号和分隔符</td><td>不一定适合直接做语义分析</td></tr><tr><td>AST</td><td>用节点类型和子节点表达程序结构</td><td>不自动提供绑定或类型</td></tr><tr><td>Visitor / NodePath</td><td>按明确的子节点键遍历，并携带路径上下文</td><td>不能替代作用域规则</td></tr><tr><td>Scope / Binding</td><td>连接声明、引用、遮蔽和写入</td><td>不等同于静态类型</td></tr><tr><td>TypeChecker</td><td>基于整个程序回答符号和类型问题</td><td>不能仅由孤立 AST 节点替代</td></tr><tr><td>Printer / Generator</td><td>从 AST 或编辑记录生成代码</td><td>不保证变换天然正确</td></tr><tr><td>Source Map</td><td>映射生成位置与原始位置</td><td>不保存程序语义</td></tr></tbody></table><h2 id="_3-学习路径" tabindex="-1">3. 学习路径 <a class="header-anchor" href="#_3-学习路径" aria-label="Permalink to &quot;3. 学习路径&quot;">​</a></h2><h3 id="_3-1-语法与表示" tabindex="-1">3.1 语法与表示 <a class="header-anchor" href="#_3-1-语法与表示" aria-label="Permalink to &quot;3.1 语法与表示&quot;">​</a></h3><ol><li><a href="/frontend/topics/ast-tooling/lexing-parsing">词法分析、语法分析与 AST</a>：理解 Token、文法、优先级、CST/AST 和错误位置，并实现一个可运行的表达式 Parser。</li><li><a href="/frontend/topics/ast-tooling/estree-parsers">AST 规范与 Parser 选型</a>：区分 ESTree、Babel、TypeScript 与 SWC AST，按语法覆盖、语义需求和生态选择 Parser。</li></ol><h3 id="_3-2-分析能力" tabindex="-1">3.2 分析能力 <a class="header-anchor" href="#_3-2-分析能力" aria-label="Permalink to &quot;3.2 分析能力&quot;">​</a></h3><ol start="3"><li><a href="/frontend/topics/ast-tooling/traversal-scope">AST 遍历、作用域与引用分析</a>：掌握 visitor keys、进入/退出阶段、NodePath、Scope、Binding 和安全重命名。</li><li><a href="/frontend/topics/ast-tooling/typescript-compiler-api">TypeScript Compiler API 与类型分析</a>：从 <code>SourceFile</code> 进入 <code>Program</code>、<code>Symbol</code>、<code>Type</code>、<code>Signature</code> 和诊断信息。</li></ol><h3 id="_3-3-变换与输出" tabindex="-1">3.3 变换与输出 <a class="header-anchor" href="#_3-3-变换与输出" aria-label="Permalink to &quot;3.3 变换与输出&quot;">​</a></h3><ol start="5"><li><a href="/frontend/topics/ast-tooling/transforms-semantics">AST 变换与语义保持</a>：处理绑定、求值次数、顺序、注释和幂等性，避免“结构改对、行为改错”。</li><li><a href="/frontend/topics/ast-tooling/codegen-source-map">代码生成与 Source Map</a>：比较整树打印与局部编辑，并验证生成位置可以映射回原始源码。</li></ol><h3 id="_3-4-工具形态" tabindex="-1">3.4 工具形态 <a class="header-anchor" href="#_3-4-工具形态" aria-label="Permalink to &quot;3.4 工具形态&quot;">​</a></h3><ol start="7"><li><a href="/frontend/topics/ast-tooling/babel-swc-plugins">Babel 与 SWC 插件体系</a>：理解两类插件宿主、生命周期、配置和适用边界。</li><li><a href="/frontend/topics/ast-tooling/eslint-rules">ESLint 自定义规则开发</a>：把可判断的代码约束实现为诊断、建议和安全修复。</li><li><a href="/frontend/topics/ast-tooling/codemod">Codemod 与自动化迁移</a>：把一次性迁移写成可重复、可审查、可回滚的结构化变换。</li><li><a href="/frontend/topics/ast-tooling/testing-performance">AST 工具测试、性能与版本兼容</a>：用夹具、语义断言、幂等性、基准和版本矩阵完成工程验收。</li></ol><h2 id="_4-parser-与工具形态速查" tabindex="-1">4. Parser 与工具形态速查 <a class="header-anchor" href="#_4-parser-与工具形态速查" aria-label="Permalink to &quot;4. Parser 与工具形态速查&quot;">​</a></h2><table tabindex="0"><thead><tr><th>需求</th><th>常见入口</th><th>关键判断</th></tr></thead><tbody><tr><td>JavaScript / JSX 解析</td><td>Acorn、Espree、<code>@babel/parser</code></td><td>是否需要提案语法、Token 和错误恢复</td></tr><tr><td>TypeScript 的 ESTree 风格 AST</td><td><code>@typescript-eslint/parser</code> / <code>typescript-estree</code></td><td>是否服务 ESLint，是否需要类型服务</td></tr><tr><td>TypeScript 编译语义</td><td><code>typescript</code> Compiler API</td><td>必须建立 <code>Program</code> 才有跨文件类型</td></tr><tr><td>通用 JS/TS 编译变换</td><td>Babel、SWC</td><td>插件生态、速度、部署形态与 AST 兼容性</td></tr><tr><td>自定义静态检查</td><td>ESLint Rule</td><td>问题能否局部判断，修复是否无歧义</td></tr><tr><td>大规模 API 迁移</td><td>jscodeshift、Babel、ts-morph</td><td>是否需要保留格式、类型信息和跨文件索引</td></tr><tr><td>局部文本改写并保留原格式</td><td>MagicString、Recast</td><td>是否能从 AST 精确获得修改区间</td></tr></tbody></table><p>没有“通用 AST”能够无损覆盖所有工具。Parser 的节点规范、语法插件、注释挂载、位置信息和版本都属于输入契约，必须与遍历器和生成器匹配。</p><h2 id="_5-选择分析层级" tabindex="-1">5. 选择分析层级 <a class="header-anchor" href="#_5-选择分析层级" aria-label="Permalink to &quot;5. 选择分析层级&quot;">​</a></h2><h3 id="_5-1-token-足够的场景" tabindex="-1">5.1 Token 足够的场景 <a class="header-anchor" href="#_5-1-token-足够的场景" aria-label="Permalink to &quot;5.1 Token 足够的场景&quot;">​</a></h3><p>只需要识别注释、统计字面量或实现语法高亮时，Token 流可能已经足够。它启动快、数据小，但不能可靠判断嵌套结构和标识符角色。</p><h3 id="_5-2-ast-足够的场景" tabindex="-1">5.2 AST 足够的场景 <a class="header-anchor" href="#_5-2-ast-足够的场景" aria-label="Permalink to &quot;5.2 AST 足够的场景&quot;">​</a></h3><p>检查调用形态、改写导入声明、生成依赖图时，语法 AST 通常足够。此时仍要使用具体生态提供的 visitor keys 或遍历器，不应递归任意对象属性。</p><h3 id="_5-3-必须使用语义信息的场景" tabindex="-1">5.3 必须使用语义信息的场景 <a class="header-anchor" href="#_5-3-必须使用语义信息的场景" aria-label="Permalink to &quot;5.3 必须使用语义信息的场景&quot;">​</a></h3><p>当问题涉及同名遮蔽、跨文件导出、重载解析、泛型实例化或真实类型时，仅看节点文本不够。应使用 Babel Scope、ESLint Scope 或 TypeScript <code>TypeChecker</code>；其中只有 TypeScript Checker 能回答完整的 TypeScript 类型问题。</p><h2 id="_6-代码工具的正确性标准" tabindex="-1">6. 代码工具的正确性标准 <a class="header-anchor" href="#_6-代码工具的正确性标准" aria-label="Permalink to &quot;6. 代码工具的正确性标准&quot;">​</a></h2><p>一个工具“能够生成代码”不代表它正确。至少需要验证：</p><ul><li><strong>语法正确</strong>：输出能被目标 Parser 再次解析；</li><li><strong>绑定正确</strong>：没有误改同名但不同声明的标识符；</li><li><strong>行为正确</strong>：求值顺序、次数、<code>this</code>、异常和异步边界没有意外变化；</li><li><strong>输出可追踪</strong>：诊断位置和 Source Map 能指回原始源码；</li><li><strong>变换可重复</strong>：对已迁移代码再次运行不会继续改变结果；</li><li><strong>版本可控</strong>：Parser、AST schema、插件宿主和生成器使用经过验证的组合。</li></ul><h2 id="_7-推荐实践顺序" tabindex="-1">7. 推荐实践顺序 <a class="header-anchor" href="#_7-推荐实践顺序" aria-label="Permalink to &quot;7. 推荐实践顺序&quot;">​</a></h2><p>先在单文件夹具中确认节点形态，再实现只读分析；随后加入最小变换和结构断言，最后才接入目录扫描、并发和写文件。生产迁移应先 dry run、输出变更统计和 diff，再在版本控制保护下写入。不要在未经审查的源码上执行生成结果，也不要把“输出可以解析”当作语义等价证明。</p><h2 id="_8-参考资料" tabindex="-1">8. 参考资料 <a class="header-anchor" href="#_8-参考资料" aria-label="Permalink to &quot;8. 参考资料&quot;">​</a></h2><ul><li><a href="https://github.com/estree/estree" target="_blank" rel="noreferrer">ESTree Spec</a></li><li><a href="https://babeljs.io/docs/babel-parser" target="_blank" rel="noreferrer">Babel Parser</a></li><li><a href="https://github.com/microsoft/TypeScript/wiki/Using-the-Compiler-API" target="_blank" rel="noreferrer">TypeScript Compiler API</a></li><li><a href="https://eslint.org/docs/latest/extend/custom-rules" target="_blank" rel="noreferrer">ESLint：Custom Rules</a></li><li><a href="https://github.com/facebook/jscodeshift" target="_blank" rel="noreferrer">jscodeshift</a></li><li><a href="https://tc39.es/ecma426/" target="_blank" rel="noreferrer">ECMA-426：Source Map Format</a></li></ul>`,35)])])}const u=e(n,[["render",s]]);export{b as __pageData,u as default};
